p.m:
\displaystyle{\begin{aligned}
   7\div \frac{7}{3} 
       \amp = \frac{7}{1} \div \frac{7}{3} \\
       \amp = \frac{7}{1} \cdot \frac{3}{7} \amp \hbox{We can divide 7 and 7 by 7 and made those two values smaller.}\\
       \amp = \frac{1}{1}\cdot\frac{3}{1} \\
       \amp = \frac{1\cdot3}{1 \cdot 1} \\
       \amp = 3
\end{aligned}
    }
